import base64
import nbformat
from django.conf import settings
from django.core.management.base import BaseCommand, CommandError
from course.models import Lesson, Asset
from course.services.submissions import new_asset, validate_asset
from course.integrations.storage.client import client, bucket

VIDEO_BASE64 = ""


class Command(BaseCommand):
    help = "Add synthetic private demo videos, starter notebooks and instructor reference notebooks"

    def handle(self, *args, **options):
        if not settings.DEBUG:
            raise CommandError("Demo media is development-only")
        for lesson in Lesson.objects.filter(
            module__course__frontend_enabled=True
        ).select_related("module__course"):
            if lesson.module.course.title not in [
                "Data Science Foundations",
                "Applied Notebook Projects",
            ]:
                continue
            if lesson.lesson_type == "video":
                self.asset(lesson, "course", "demo.mp4", base64.b64decode(VIDEO_BASE64))
            elif lesson.lesson_type == "exercise":
                notebook = nbformat.v4.new_notebook(
                    cells=[
                        nbformat.v4.new_markdown_cell(
                            "# Databrix\nSave this notebook in your DHBW workspace. Export it after completing the exercise."
                        ),
                        nbformat.v4.new_code_cell("print(1 + 1)"),
                    ]
                )
                data = nbformat.writes(notebook).encode()
                self.asset(lesson, "course", "starter.ipynb", data)
                self.asset(lesson, "assessment", "reference.ipynb", data)
        self.stdout.write(
            "Synthetic private demo media is ready; DHBW working folders were not changed"
        )

    def asset(self, lesson, category, name, data):
        source = f"demo:{lesson.pk}:{category}:{name}"
        if Asset.objects.filter(legacy_source=source, status="accepted").exists():
            return
        a, _ = new_asset(
            lesson.module.instructor,
            name,
            len(data),
            category,
            course=lesson.module.course,
            lesson=lesson,
        )
        a.legacy_source = source
        a.save(update_fields=["legacy_source"])
        client(category).put_object(
            Bucket=bucket(category),
            Key=a.staging_key,
            Body=data,
            ContentType=a.content_type,
        )
        validate_asset(a)
